// The release note the app bundles, read into plain structs.
//
// Assets/ReleaseNotes.json is GENERATED by the localization store from its
// release-notes/latest.yaml (urnetwork/localizations, npm run gen): edit the
// store, never the asset. Every app reads the same shape,
//   {"version": "2026.11", "date": "2026-11-19",
//    "locales": {"en": {"title": "...", "intro": "...",
//                       "sections": [{"heading": "...", "items": ["...", ...]}]},
//                ...}}
// where intro and a section's heading are optional, sections may be empty, and
// en is the one locale every note carries.
//
// Every app shows it by one rule (the store's README, "Release notes"). The
// note is in the app's own UI language (PickLocale): that exact store locale;
// else the same language in another form, the bare language first (pt-BR ->
// pt) and then another region of it (pt-PT -> pt-BR), never across Chinese
// scripts (the store's zh is Simplified, zh-HK Traditional); else en. It is
// laid out in its own language's direction (IsRightToLeft), so the English
// fallback reads left to right in an Arabic or Hebrew UI. The line under its
// title is the running build's version, as the App version row shows it, with
// the note's date, a calendar day no time zone moves (MetaLine, EpochDays;
// owner 2026-11-19): the note's own version is read but not shown.
//
// The file is read the way Common/ReleaseJson.h reads another service's JSON:
// every read is a find and a type check, so a file that is not this shape is no
// note at all (nullopt) and nothing here throws. Settings' App version row then
// stays the plain value row it was, rather than opening an empty sheet.
//
// Needs nlohmann/json and nothing of Windows: tools/release-notes-tests.cpp runs
// it on any host that has the library.
//
// SPDX-License-Identifier: MPL-2.0
#pragma once

#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include <nlohmann/json.hpp>

namespace urnw::releasenotes {

// One section of the note: its heading ("" for none) and its bullets, in order.
struct Section {
  std::string heading;
  std::vector<std::string> items;
};

// The note, in the one locale shown.
struct Note {
  // the release the note describes, as people see it ("2026.11"); not shown,
  // since the line under the title names the running build (MetaLine)
  std::string version;
  // the release day as the file spells it, YYYY-MM-DD ("" when it has none)
  std::string date;
  // the store locale the text below is in
  std::string locale;
  std::string title;
  // "" for a note without one
  std::string intro;
  // those with at least one bullet; possibly none
  std::vector<Section> sections;
};

// A calendar day, so the date can be shown in the reader's own format.
struct Day {
  int year = 0;
  int month = 0;
  int day = 0;
};

namespace detail {

constexpr char Lower(char c) { return c >= 'A' && c <= 'Z' ? static_cast<char>(c - 'A' + 'a') : c; }
constexpr bool IsAlpha(char c) { return ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z'); }
constexpr bool IsDigit(char c) { return '0' <= c && c <= '9'; }

// One language tag the same as another, whatever the case, with '_' read as
// '-' ("zh_HK" is "zh-HK").
constexpr bool SameTag(std::string_view a, std::string_view b) {
  if (a.size() != b.size()) return false;
  for (std::size_t i = 0; i < a.size(); ++i) {
    const char x = a[i] == '_' ? '-' : Lower(a[i]);
    const char y = b[i] == '_' ? '-' : Lower(b[i]);
    if (x != y) return false;
  }
  return true;
}

// Every character of a subtag passes `test`; false for an empty one.
template <typename Test>
constexpr bool All(std::string_view part, Test test) {
  if (part.empty()) return false;
  for (const char c : part) {
    if (!test(c)) return false;
  }
  return true;
}

// A BCP 47 tag's language, script and region, lowercase: "zh-Hant-TW" is zh,
// hant, tw; "es-419" is es, "", 419. Variants and extensions are dropped.
struct Subtags {
  std::string language;
  std::string script;
  std::string region;
};

inline Subtags Split(std::string_view tag) {
  Subtags out;
  bool first = true;
  while (!tag.empty()) {
    const std::size_t end = tag.find_first_of("-_");
    const std::string_view part = tag.substr(0, end);
    tag = end == std::string_view::npos ? std::string_view{} : tag.substr(end + 1);
    std::string lower(part);
    for (char& c : lower) c = Lower(c);
    if (first) {
      out.language = std::move(lower);
      first = false;
    } else if (part.size() == 4 && All(part, IsAlpha) && out.script.empty() && out.region.empty()) {
      out.script = std::move(lower);
    } else if (out.region.empty() &&
               ((part.size() == 2 && All(part, IsAlpha)) || (part.size() == 3 && All(part, IsDigit)))) {
      out.region = std::move(lower);
    }
  }
  return out;
}

// Whether a Chinese tag writes Traditional characters: an explicit script
// decides, else Taiwan, Hong Kong and Macau do, and every other region (and no
// region at all, the store's bare zh) writes Simplified.
inline bool TraditionalChinese(Subtags const& tag) {
  if (tag.script == "hant") return true;
  if (tag.script == "hans") return false;
  return tag.region == "tw" || tag.region == "hk" || tag.region == "mo";
}

inline std::string Text(nlohmann::json const& object, const char* field) {
  const auto it = object.find(field);
  if (it == object.end() || !it->is_string()) return {};
  return it->get<std::string>();
}

}  // namespace detail

// Which of the note's `locales` to show for the UI language `language` (a BCP
// 47 tag such as "pt-BR"; of a list, "fr-FR;en-US", the first, which the UI is
// in): that exact locale; else, for Chinese, only the store locale of the same
// script (zh for zh-Hans, zh-CN and a bare zh; zh-HK for zh-Hant, zh-HK, zh-TW
// and zh-MO); else, for any other language, the bare language and then another
// region of it, in the order given; else en. "" when the note has none of them.
inline std::string PickLocale(std::vector<std::string> const& locales, std::string_view language) {
  language = language.substr(0, language.find(';'));
  if (!language.empty()) {
    for (auto const& locale : locales) {
      if (detail::SameTag(locale, language)) return locale;
    }
  }
  const detail::Subtags ui = detail::Split(language);
  if (ui.language == "zh") {
    const std::string_view sameScript = detail::TraditionalChinese(ui) ? "zh-HK" : "zh";
    for (auto const& locale : locales) {
      if (detail::SameTag(locale, sameScript)) return locale;
    }
  } else if (!ui.language.empty()) {
    for (auto const& locale : locales) {
      if (detail::SameTag(locale, ui.language)) return locale;
    }
    for (auto const& locale : locales) {
      if (detail::Split(locale).language == ui.language) return locale;
    }
  }
  for (auto const& locale : locales) {
    if (detail::SameTag(locale, "en")) return locale;
  }
  return {};
}

// The line under the note's title (owner 2026-11-19): `runningVersion`, the
// running build's version exactly as the tapped App version row shows it, then
// `date`, the note's date as the reader's format writes it, with a middle dot
// between them; either alone when the other is empty. Never the note's own
// version. Both are data, so the dot hides no string from the store.
inline std::wstring MetaLine(std::wstring_view runningVersion, std::wstring_view date) {
  std::wstring line(runningVersion);
  if (!line.empty() && !date.empty()) line += L" \u00B7 ";
  line += date;
  return line;
}

// Whether a locale's text reads right to left: the store's Arabic and Hebrew,
// and the other right-to-left languages a note could one day carry.
inline bool IsRightToLeft(std::string_view locale) {
  const std::string language = detail::Split(locale).language;
  for (const std::string_view rtl : {"ar", "dv", "fa", "he", "ps", "sd", "ug", "ur", "yi"}) {
    if (language == rtl) return true;
  }
  return false;
}

// The note `body` carries, in the locale PickLocale picks for `language`.
// nullopt when the body is not a JSON object with a "locales" object, when no
// locale fits, or when the one picked has no title. Within the note, a missing
// or mistyped field reads as empty, and a section or bullet that is not the
// shape, or a section with no bullet, is skipped.
inline std::optional<Note> Parse(std::string_view body, std::string_view language) {
  // parse(..., false): a malformed body comes back as discarded, not a throw
  const nlohmann::json document = nlohmann::json::parse(body.begin(), body.end(), nullptr, false);
  if (!document.is_object()) return std::nullopt;
  const auto locales = document.find("locales");
  if (locales == document.end() || !locales->is_object()) return std::nullopt;
  std::vector<std::string> available;
  for (auto it = locales->begin(); it != locales->end(); ++it) {
    if (it.value().is_object()) available.push_back(it.key());
  }
  const std::string locale = PickLocale(available, language);
  if (locale.empty()) return std::nullopt;
  const nlohmann::json& text = *locales->find(locale);

  Note note;
  note.version = detail::Text(document, "version");
  note.date = detail::Text(document, "date");
  note.locale = locale;
  note.title = detail::Text(text, "title");
  if (note.title.empty()) return std::nullopt;
  note.intro = detail::Text(text, "intro");
  const auto sections = text.find("sections");
  if (sections != text.end() && sections->is_array()) {
    for (auto const& entry : *sections) {
      if (!entry.is_object()) continue;
      Section section;
      section.heading = detail::Text(entry, "heading");
      const auto items = entry.find("items");
      if (items != entry.end() && items->is_array()) {
        for (auto const& item : *items) {
          if (!item.is_string()) continue;
          std::string words = item.get<std::string>();
          if (!words.empty()) section.items.push_back(std::move(words));
        }
      }
      if (!section.items.empty()) note.sections.push_back(std::move(section));
    }
  }
  return note;
}

// The days of `month` (1 to 12) in `year`, in the Gregorian calendar.
constexpr int DaysInMonth(int year, int month) {
  constexpr int kDays[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  const bool leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
  return month == 2 && leap ? 29 : kDays[month - 1];
}

// The day a YYYY-MM-DD date names; nullopt for any other spelling, or for a
// day the calendar does not have.
constexpr std::optional<Day> ParseDay(std::string_view date) {
  if (date.size() != 10 || date[4] != '-' || date[7] != '-') return std::nullopt;
  int fields[3] = {0, 0, 0};
  const std::size_t starts[3] = {0, 5, 8};
  const std::size_t lengths[3] = {4, 2, 2};
  for (std::size_t f = 0; f < 3; ++f) {
    for (std::size_t i = starts[f]; i < starts[f] + lengths[f]; ++i) {
      if (!detail::IsDigit(date[i])) return std::nullopt;
      fields[f] = fields[f] * 10 + (date[i] - '0');
    }
  }
  if (fields[0] < 1 || fields[1] < 1 || 12 < fields[1] || fields[2] < 1 ||
      DaysInMonth(fields[0], fields[1]) < fields[2]) {
    return std::nullopt;
  }
  return Day{fields[0], fields[1], fields[2]};
}

// The days from 1970-01-01 to `day` (Howard Hinnant's days_from_civil).
// Midnight UTC of that day, formatted in UTC, is that day in every time zone.
constexpr std::int64_t EpochDays(Day const& day) {
  const std::int64_t year = day.year - (day.month <= 2 ? 1 : 0);
  const std::int64_t era = (0 <= year ? year : year - 399) / 400;
  const std::int64_t yearOfEra = year - era * 400;
  const std::int64_t dayOfYear = (153 * ((day.month + 9) % 12) + 2) / 5 + day.day - 1;
  const std::int64_t dayOfEra = yearOfEra * 365 + yearOfEra / 4 - yearOfEra / 100 + dayOfYear;
  return era * 146097 + dayOfEra - 719468;
}

}  // namespace urnw::releasenotes
